package com.osrs.accessdenied;

import com.formdev.flatlaf.FlatClientProperties;
import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JLabel;
import javax.swing.JToggleButton;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel for the plugin's in-the-moment toggles — the settings you flip mid-session
 * rather than configure once. Every control writes straight to the plugin's config group,
 * so the value persists and the plugin picks it up through its normal ConfigChanged path.
 */
@Singleton
public class AccessDeniedPanel extends PluginPanel
{
	private static final String NPCS_HIDDEN = "NPCs hidden";
	private static final String NPCS_VISIBLE = "NPCs visible";

	/**
	 * FlatLaf resolves a selected button's colours from the look and feel's
	 * ToggleButton.selected* defaults and never reads the component's own background or
	 * foreground, so plain setters go unused in that state. A style property is the supported
	 * way to override them per component; setting one also unshares this button's UI
	 * delegate, which keeps the override off every other toggle button in the client.
	 */
	private static final String SELECTED_STYLE = String.format(
		"selectedBackground: #%06X; selectedForeground: #%06X",
		ColorScheme.BRAND_ORANGE.getRGB() & 0xFFFFFF,
		Color.BLACK.getRGB() & 0xFFFFFF);

	private final JToggleButton hideNpcsToggle = new JToggleButton();

	@Inject
	public AccessDeniedPanel(ConfigManager configManager)
	{
		JLabel title = new JLabel("Access Denied");
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		add(title);

		hideNpcsToggle.setFocusPainted(false);
		hideNpcsToggle.setToolTipText("Hide all NPCs, along with their health bars, overhead prayers and"
			+ " hitsplats. Hidden NPCs cannot be clicked.");
		// FlatLaf reads these two only while the button is unselected; the selected pair comes
		// from the style below.
		hideNpcsToggle.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		hideNpcsToggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		hideNpcsToggle.putClientProperty(FlatClientProperties.STYLE, SELECTED_STYLE);
		// An ItemListener fires for a click and for setSelected alike, so the label always
		// matches the button. An ActionListener fires only on a click, so syncing the button
		// from a config change cannot loop back into another config write.
		hideNpcsToggle.addItemListener(e -> updateToggleText());
		hideNpcsToggle.addActionListener(e -> configManager.setConfiguration(
			AccessDeniedConfig.CONFIG_GROUP,
			AccessDeniedConfig.HIDE_NPCS_KEY,
			hideNpcsToggle.isSelected()));
		updateToggleText();
		add(hideNpcsToggle);
	}

	/**
	 * Reflects the stored value back into the button. Called from config and profile changes,
	 * which do not necessarily arrive on the AWT event thread.
	 */
	void setHideNpcs(boolean hideNpcs)
	{
		SwingUtilities.invokeLater(() -> hideNpcsToggle.setSelected(hideNpcs));
	}

	/**
	 * The button states which way it is currently set rather than what clicking it will do.
	 * A checkmark is not legible here: at sidebar size it is a few dark pixels against the
	 * panel's dark grey, so the state has to be carried by the text and the colour.
	 */
	private void updateToggleText()
	{
		hideNpcsToggle.setText(hideNpcsToggle.isSelected() ? NPCS_HIDDEN : NPCS_VISIBLE);
	}
}

package com.osrs.accessdenied;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.raids.Raid;
import net.runelite.client.plugins.raids.RaidRoom;
import net.runelite.client.plugins.raids.RoomType;
import net.runelite.client.plugins.raids.events.RaidReset;
import net.runelite.client.plugins.raids.events.RaidScouted;
import net.runelite.client.plugins.raids.solver.Room;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Slf4j
@PluginDescriptor(
	name = "Access Denied"
)
public class AccessDeniedPlugin extends Plugin
{
	private static final String RELEASE_LOCK_OPTION = "Release raid lock";

	@Inject
	private Client client;

	@Inject
	private AccessDeniedConfig config;

	@Inject
	private PlayerStateValidator playerStateValidator;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private NpcHider npcHider;

	@Inject
	private AccessDeniedPanel panel;

	private NavigationButton navButton;

	private BossLocation currentLocation;

	/**
	 * Requirements the player failed at {@link #currentLocation} as of the last check.
	 * Null means "not checked yet", empty means everything is satisfied.
	 */
	private List<String> lastMissing;
	private boolean lastResultWasValid = true;
	private Raid currentCoxRaid;
	private boolean coxScoutingRaidGood = false;
	private String coxScoutingReleasedLayout;

	@Override
	protected void startUp()
	{
		resetState();
		migrateLegacyConfig();

		npcHider.startUp();
		applyHideNpcs();

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Access Denied")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		resetState();

		// PluginManager calls shutDown() after a startUp() that threw, so the button may never
		// have been built. ClientUI.removeNavigation dereferences its argument.
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		npcHider.shutDown();
	}

	/**
	 * Pushes the stored Hide NPCs value into the renderer and back into the side panel, so
	 * the two agree no matter which of them (or which profile) changed it.
	 */
	private void applyHideNpcs()
	{
		boolean hideNpcs = config.hideNpcs();
		npcHider.setHideNpcs(hideNpcs);
		panel.setHideNpcs(hideNpcs);
	}

	private void resetState()
	{
		currentLocation = null;
		lastMissing = null;
		lastResultWasValid = true;
		currentCoxRaid = null;
		coxScoutingRaidGood = false;
		coxScoutingReleasedLayout = null;
	}

	/**
	 * Brings a profile written by an older version up to date. Runs on start-up and on every
	 * profile switch, since ConfigManager.switchProfile() never re-invokes startUp().
	 */
	private void migrateLegacyConfig()
	{
		// coxScoutWhitelistedRooms listed the rooms a raid was permitted to contain;
		// coxScoutRequiredRooms lists the ones it must contain. Carrying the value across
		// would reverse its meaning and produce a filter that can never match, so the old
		// key is dropped rather than migrated.
		if (configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxScoutWhitelistedRooms") != null)
		{
			configManager.unsetConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxScoutWhitelistedRooms");
		}

		// The layout key was only renamed — its values still mean exactly what they did.
		String legacyLayouts = configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxScoutWhitelistedLayouts");
		if (legacyLayouts != null)
		{
			if (configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxScoutAllowedLayouts") == null)
			{
				configManager.setConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxScoutAllowedLayouts", legacyLayouts);
			}
			configManager.unsetConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxScoutWhitelistedLayouts");
		}

		migrateLegacyCoxSpellConfig();
	}

	/**
	 * Carries forward the four legacy CoX boolean toggles (coxRequireSpell/
	 * coxRequireDeathCharge/coxRequireHumidify/coxRequireVengeance) into the
	 * coxSpellRequirement enum they were replaced by, then removes the old keys. Without
	 * this, users who had one of those toggles enabled would silently lose their CoX
	 * requirement on upgrade, since nothing reads the old keys any more.
	 */
	private void migrateLegacyCoxSpellConfig()
	{
		String legacySpell = configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireSpell");
		String legacyDeathCharge = configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireDeathCharge");
		String legacyHumidify = configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireHumidify");
		String legacyVengeance = configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireVengeance");

		if (legacySpell == null && legacyDeathCharge == null && legacyHumidify == null && legacyVengeance == null)
		{
			return;
		}

		if (configManager.getConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxSpellRequirement") == null)
		{
			configManager.setConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxSpellRequirement",
				CoxSpellRequirement.fromLegacyFlags(
					Boolean.parseBoolean(legacySpell),
					Boolean.parseBoolean(legacyDeathCharge),
					Boolean.parseBoolean(legacyHumidify),
					Boolean.parseBoolean(legacyVengeance)));
		}

		configManager.unsetConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireSpell");
		configManager.unsetConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireDeathCharge");
		configManager.unsetConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireHumidify");
		configManager.unsetConfiguration(AccessDeniedConfig.CONFIG_GROUP, "coxRequireVengeance");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN && event.getGameState() != GameState.LOADING)
		{
			return;
		}

		if (client.getLocalPlayer() == null)
		{
			return;
		}

		BossLocation newLocation = BossLocation.findByRegions(client.getTopLevelWorldView().getMapRegions());

		if (newLocation != currentLocation)
		{
			currentLocation = newLocation;
			lastMissing = null;
			lastResultWasValid = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (coxRaidInProgress() || currentLocation == null || !currentLocation.requiresValidation(config))
		{
			lastMissing = null;
			lastResultWasValid = true;
			return;
		}

		lastMissing = findMissingRequirements(currentLocation);

		boolean valid = lastMissing.isEmpty();
		if (!valid && lastResultWasValid)
		{
			sendChatMessage(describe(lastMissing));
		}

		lastResultWasValid = valid;
	}

	@Subscribe
	public void onRaidScouted(RaidScouted event)
	{
		currentCoxRaid = event.getRaid();
		evaluateCoxScoutingRaid();
	}

	@Subscribe
	public void onRaidReset(RaidReset event)
	{
		currentCoxRaid = null;
		coxScoutingRaidGood = false;
		coxScoutingReleasedLayout = null;
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// ConfigManager.switchProfile() never re-invokes startUp(), so a profile with
		// un-migrated legacy CoX keys would otherwise keep reading them as unset forever.
		migrateLegacyConfig();

		// A profile switch replaces every value at once without raising a ConfigChanged per
		// key, so the panel and renderer have to be re-read from the new profile here.
		applyHideNpcs();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AccessDeniedConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		// Returns rather than falling through: the reset below re-arms the "Missing: ..."
		// chat warning, so without this every click of the sidebar toggle would repeat a
		// warning the player has already been given.
		if (AccessDeniedConfig.HIDE_NPCS_KEY.equals(event.getKey()))
		{
			applyHideNpcs();
			return;
		}

		warnIfEnabledWithoutRequirements(event.getKey());

		// Reset state so the next tick re-evaluates with the new config
		lastMissing = null;
		lastResultWasValid = true;

		if (event.getKey().startsWith("coxScout"))
		{
			evaluateCoxScoutingRaid();
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		int eventType = event.getType();
		if (eventType != MenuAction.GAME_OBJECT_FIRST_OPTION.getId()
			&& eventType != MenuAction.GAME_OBJECT_SECOND_OPTION.getId())
		{
			return;
		}

		// Inside a running raid the entrance object ID is reused by ordinary doors, so
		// every swap from here on would land on the wrong door. Nothing needs blocking
		// once the raid has begun anyway.
		if (coxRaidInProgress())
		{
			return;
		}

		int objectId = event.getIdentifier();

		if (currentLocation != null && currentLocation.getObjectId() == objectId)
		{
			// The first menu open can happen before the first game tick has validated;
			// compute on demand so right-clicking immediately on arrival is still protected.
			// When validation isn't required, lastMissing stays null and this cheap
			// requiresValidation check simply re-runs per event — onGameTick owns the
			// cache lifecycle (it nulls lastMissing every tick when validation is off), so
			// there is no cache to populate here. lastResultWasValid is intentionally left
			// untouched: onGameTick alone decides whether the chat warning fires, so an
			// invalid result computed here doesn't get treated as "already warned about".
			if (lastMissing == null && currentLocation.requiresValidation(config))
			{
				lastMissing = findMissingRequirements(currentLocation);
			}

			if (lastMissing != null && !lastMissing.isEmpty())
			{
				reorderMenuToWalkHere(client.getMenu().getMenuEntries());
				return;
			}
		}

		if (objectId == BossLocation.COX_RELOAD_OBJECT && coxScoutingRaidGood)
		{
			removeGameObjectEntriesForObject(BossLocation.COX_RELOAD_OBJECT);
			addReleaseLockEntry();
		}
	}

	private void evaluateCoxScoutingRaid()
	{
		if (!config.coxScoutingEnabled() || currentCoxRaid == null)
		{
			coxScoutingRaidGood = false;
			return;
		}

		if (currentCoxRaid.getLayout().toCodeString().equalsIgnoreCase(coxScoutingReleasedLayout))
		{
			log.debug("evaluateCoxScoutingRaid: lock released by the player for this layout");
			coxScoutingRaidGood = false;
			return;
		}

		Set<String> requiredRooms = new HashSet<>(Text.fromCSV(config.coxScoutRequiredRooms().toLowerCase()));
		Set<String> disallowedRooms = new HashSet<>(Text.fromCSV(config.coxScoutDisallowedRooms().toLowerCase()));
		List<String> layoutWhitelist = Text.fromCSV(config.coxScoutAllowedLayouts().toLowerCase());

		if (requiredRooms.isEmpty() && disallowedRooms.isEmpty() && layoutWhitelist.isEmpty())
		{
			coxScoutingRaidGood = false;
			return;
		}

		if (!requiredRooms.isEmpty() || !disallowedRooms.isEmpty())
		{
			Set<RaidRoom> rooms = combatAndPuzzleRooms();

			// A room the player has not walked to yet still reports type COMBAT/PUZZLE, so it
			// would slip past the disallowed check and lock a raid that may yet turn out bad.
			// Wait for the scout to finish instead.
			if (rooms.contains(RaidRoom.UNKNOWN_COMBAT) || rooms.contains(RaidRoom.UNKNOWN_PUZZLE))
			{
				log.debug("evaluateCoxScoutingRaid: raid is not fully scouted yet — raid is bad");
				coxScoutingRaidGood = false;
				return;
			}

			Set<String> raidRooms = new HashSet<>();
			for (RaidRoom room : rooms)
			{
				raidRooms.add(room.getName().toLowerCase());
			}

			// Required rooms must all be present; disallowed rooms must all be absent. Anything
			// in neither list is ignored, so a raid is judged only on what was asked about.
			Set<String> missing = new HashSet<>(requiredRooms);
			missing.removeAll(raidRooms);

			Set<String> disallowed = new HashSet<>(raidRooms);
			disallowed.retainAll(disallowedRooms);

			if (!missing.isEmpty())
			{
				log.debug("evaluateCoxScoutingRaid: raid is missing required rooms {} — raid is bad", missing);
				coxScoutingRaidGood = false;
				return;
			}

			if (!disallowed.isEmpty())
			{
				log.debug("evaluateCoxScoutingRaid: raid contains disallowed rooms {} — raid is bad", disallowed);
				coxScoutingRaidGood = false;
				return;
			}
		}

		if (!layoutWhitelist.isEmpty())
		{
			// Entries match by prefix so a partial code like "fscc" selects a family of layouts.
			// A full code is its own prefix and still matches only itself: no layout in the
			// client's table is a prefix of a different one.
			String layoutCode = currentCoxRaid.getLayout().toCodeString().toLowerCase();
			if (layoutWhitelist.stream().noneMatch(layoutCode::startsWith))
			{
				log.debug("evaluateCoxScoutingRaid: layout '{}' matches no whitelisted layout or prefix — raid is bad", layoutCode);
				coxScoutingRaidGood = false;
				return;
			}
		}

		boolean wasGood = coxScoutingRaidGood;
		coxScoutingRaidGood = true;

		if (!wasGood)
		{
			sendChatMessage("Good raid found — reload protection active.");
		}
	}

	/**
	 * Adds the escape hatch for the reload block: right-clicking the reload object still
	 * offers a way out, since the block itself removes every game option on it. Inserted at
	 * index 0 (the bottom of the menu) so it can never become the left-click action — a
	 * stray click must not be able to unlock and then reload a good raid.
	 */
	private void addReleaseLockEntry()
	{
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		for (MenuEntry entry : entries == null ? new MenuEntry[0] : entries)
		{
			if (RELEASE_LOCK_OPTION.equals(entry.getOption()))
			{
				// The object can contribute several entries, one event each — only one hatch.
				return;
			}
		}

		client.getMenu().createMenuEntry(0)
			.setOption(RELEASE_LOCK_OPTION)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> releaseCoxScoutingLock());
	}

	/**
	 * The raid's combat and puzzle rooms. Farming, scavenger and empty rooms are deliberately
	 * excluded: they are not what players filter raids on.
	 */
	private Set<RaidRoom> combatAndPuzzleRooms()
	{
		Set<RaidRoom> rooms = new HashSet<>();
		for (Room layoutRoom : currentCoxRaid.getLayout().getRooms())
		{
			RaidRoom room = currentCoxRaid.getRoom(layoutRoom.getPosition());
			if (room != null && (room.getType() == RoomType.COMBAT || room.getType() == RoomType.PUZZLE))
			{
				rooms.add(room);
			}
		}
		return rooms;
	}

	/**
	 * Chat output must happen on the client thread, but config edits arrive on the AWT event
	 * thread — sending from there trips the client's own assertion and aborts the caller
	 * mid-evaluation. invoke() still runs inline when already on the client thread.
	 */
	private void sendChatMessage(String message)
	{
		clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
	}

	private void releaseCoxScoutingLock()
	{
		coxScoutingRaidGood = false;
		coxScoutingReleasedLayout = currentCoxRaid != null ? currentCoxRaid.getLayout().toCodeString() : null;
		sendChatMessage("Reload protection released — the reload option is available again.");
	}

	private void removeGameObjectEntriesForObject(int objectId)
	{
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries == null || entries.length == 0)
		{
			return;
		}

		List<MenuEntry> kept = new ArrayList<>();
		for (MenuEntry entry : entries)
		{
			if (entry.getIdentifier() == objectId
				&& (entry.getType() == MenuAction.GAME_OBJECT_FIRST_OPTION
					|| entry.getType() == MenuAction.GAME_OBJECT_SECOND_OPTION))
			{
				continue;
			}
			kept.add(entry);
		}

		if (kept.size() < entries.length)
		{
			client.getMenu().setMenuEntries(kept.toArray(new MenuEntry[0]));
		}
	}

	private void reorderMenuToWalkHere(MenuEntry[] menuEntries)
	{
		if (menuEntries == null || menuEntries.length == 0)
		{
			return;
		}

		int walkHereIndex = -1;
		for (int i = 0; i < menuEntries.length; i++)
		{
			if (menuEntries[i].getType() == MenuAction.WALK)
			{
				walkHereIndex = i;
				break;
			}
		}

		// The last entry is the left-click option, so an absent or already-last Walk Here
		// leaves nothing to do.
		if (walkHereIndex == -1 || walkHereIndex == menuEntries.length - 1)
		{
			return;
		}

		MenuEntry walkHereEntry = menuEntries[walkHereIndex];
		MenuEntry[] reordered = new MenuEntry[menuEntries.length];

		int newIndex = 0;
		for (int i = 0; i < menuEntries.length; i++)
		{
			if (i != walkHereIndex)
			{
				reordered[newIndex++] = menuEntries[i];
			}
		}
		reordered[menuEntries.length - 1] = walkHereEntry;

		client.getMenu().setMenuEntries(reordered);
	}

	/**
	 * Warns when a location's master toggle is switched on but nothing below it is, which
	 * would otherwise look enabled while validating nothing.
	 */
	private void warnIfEnabledWithoutRequirements(String configKey)
	{
		if (!configKey.endsWith("Enabled"))
		{
			return;
		}

		for (BossLocation location : BossLocation.values())
		{
			if (!configKey.equals(location.getConfigPrefix() + "Enabled"))
			{
				continue;
			}

			if (location.isEnabled(config) && !location.hasRequirements(config))
			{
				sendChatMessage(String.format(
					"<col=ff0000>Warning: %s validation is enabled but no requirements are configured. "
						+ "Enable at least one requirement for validation to work.</col>",
					location.getDisplayName()));
			}
			return;
		}
	}

	private List<String> findMissingRequirements(BossLocation location)
	{
		List<String> missing = new ArrayList<>();

		switch (location)
		{
			case NEX:
				addArceuusChecks(missing, config.nexRequireSpell(), config.nexRequireDeathCharge());
				break;
			case TOB:
				addArceuusChecks(missing, config.tobRequireSpell(), config.tobRequireDeathCharge());
				break;
			case TOA:
				addArceuusChecks(missing, config.toaRequireSpell(), config.toaRequireDeathCharge());
				break;
			case COX:
				addCoxSpellChecks(missing);
				break;
			case INFERNO:
				addInfernoChecks(missing);
				break;
		}

		if (location.bansChugJug(config) && playerStateValidator.hasChugJug())
		{
			missing.add("remove " + location.getChugJugLabel());
		}

		if (location.bansSaturatedHeart(config) && playerStateValidator.hasSaturatedHeart())
		{
			missing.add("remove Saturated Heart");
		}

		return missing;
	}

	private void addArceuusChecks(List<String> missing, boolean requireThralls, boolean requireDeathCharge)
	{
		if (!requireThralls && !requireDeathCharge)
		{
			return;
		}

		if (requireThralls)
		{
			if (!playerStateValidator.hasResurrectGreaterGhostRunes()) { missing.add("runes for Thralls"); }
			if (!playerStateValidator.hasBookOfTheDead()) { missing.add("Book of the Dead"); }
		}

		if (requireDeathCharge && !playerStateValidator.hasDeathChargeRunes())
		{
			missing.add("runes for Death Charge");
		}

		if (!playerStateValidator.isOnArceuusSpellbook())
		{
			missing.add("Arceuus spellbook");
		}
	}

	private void addCoxSpellChecks(List<String> missing)
	{
		CoxSpellRequirement requirement = config.coxSpellRequirement();

		addArceuusChecks(missing, requirement.requiresThralls(), requirement.requiresDeathCharge());

		if (!requirement.requiresLunar())
		{
			return;
		}

		if (requirement.requiresHumidify() && !playerStateValidator.hasHumidifyRunes())
		{
			missing.add("runes for Humidify");
		}

		if (requirement.requiresVengeance() && !playerStateValidator.hasVengeanceRunes())
		{
			missing.add("runes for Vengeance");
		}

		if (!playerStateValidator.isOnLunarSpellbook())
		{
			missing.add("Lunar spellbook");
		}
	}

	private void addInfernoChecks(List<String> missing)
	{
		boolean ice = config.infernoRequireIceBarrage();
		boolean blood = config.infernoRequireBloodBarrage();

		if (ice && !playerStateValidator.hasIceBarrageRunes())
		{
			missing.add("runes for Ice Barrage");
		}

		if (blood && !playerStateValidator.hasBloodBarrageRunes())
		{
			missing.add("runes for Blood Barrage");
		}

		if ((ice || blood) && !playerStateValidator.isOnAncientSpellbook())
		{
			missing.add("Ancient spellbook");
		}
	}

	/**
	 * True once a Chambers of Xeric raid has started. Read from the varbit rather than
	 * tracked from the "The raid has begun!" message: map region churn while moving
	 * between rooms (and any relog inside the raid) used to clear a tracked flag, which
	 * brought the entrance swap back on in-raid doors sharing the entrance object ID.
	 */
	private boolean coxRaidInProgress()
	{
		return currentLocation == BossLocation.COX
			&& client.getVarbitValue(VarbitID.RAIDS_CLIENT_PROGRESS) > 0;
	}

	private static String describe(List<String> missing)
	{
		return "Missing: " + String.join(", ", missing);
	}

	@Provides
	AccessDeniedConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AccessDeniedConfig.class);
	}
}

package com.osrs.accessdenied;

import java.util.function.Predicate;

/**
 * The boss locations the plugin guards: the map regions that identify each one, the game
 * object whose menu entry is protected, and the config accessors for its requirements.
 *
 * <p>Constant names double as the config key prefix, so {@code NEX} owns {@code nexEnabled},
 * {@code nexBanChugJug} and so on.
 */
public enum BossLocation
{
	/**
	 * Object 42967 is the barrier while the room is available; 42968 (busy) is deliberately
	 * not guarded, since entering is impossible then anyway.
	 */
	NEX("Nex", 42967, new int[]{11601},
		AccessDeniedConfig::nexEnabled,
		c -> c.nexRequireSpell() || c.nexRequireDeathCharge(),
		AccessDeniedConfig::nexBanChugJug,
		AccessDeniedConfig::nexBanSaturatedHeart,
		"Chug Jug"),

	TOB("Theatre of Blood", 32653, new int[]{14642},
		AccessDeniedConfig::tobEnabled,
		c -> c.tobRequireSpell() || c.tobRequireDeathCharge(),
		AccessDeniedConfig::tobBanChugJug,
		AccessDeniedConfig::tobBanSaturatedHeart,
		"Chug Jug"),

	TOA("Tombs of Amascut", 46089, new int[]{13454},
		AccessDeniedConfig::toaEnabled,
		c -> c.toaRequireSpell() || c.toaRequireDeathCharge(),
		AccessDeniedConfig::toaBanChugJug,
		AccessDeniedConfig::toaBanSaturatedHeart,
		"Chug Jug"),

	COX("Chambers of Xeric", 29789, new int[]{13393, 13137},
		AccessDeniedConfig::coxEnabled,
		c -> c.coxSpellRequirement() != CoxSpellRequirement.NONE,
		AccessDeniedConfig::coxBanChugJug,
		AccessDeniedConfig::coxBanSaturatedHeart,
		"Chugging Barrel"),

	INFERNO("Inferno", 30352, new int[]{10063, 9807},
		AccessDeniedConfig::infernoEnabled,
		c -> c.infernoRequireIceBarrage() || c.infernoRequireBloodBarrage(),
		AccessDeniedConfig::infernoBanChugJug,
		AccessDeniedConfig::infernoBanSaturatedHeart,
		"Chug Jug");

	/**
	 * The CoX raid reload interaction, guarded during scouting rather than on entry, so it
	 * belongs to no single location's validation.
	 */
	public static final int COX_RELOAD_OBJECT = 49999;

	private final String displayName;
	private final int objectId;
	private final int[] regions;
	private final Predicate<AccessDeniedConfig> enabled;
	private final Predicate<AccessDeniedConfig> spellRequired;
	private final Predicate<AccessDeniedConfig> bansChugJug;
	private final Predicate<AccessDeniedConfig> bansSaturatedHeart;
	private final String chugJugLabel;

	BossLocation(String displayName, int objectId, int[] regions,
		Predicate<AccessDeniedConfig> enabled,
		Predicate<AccessDeniedConfig> spellRequired,
		Predicate<AccessDeniedConfig> bansChugJug,
		Predicate<AccessDeniedConfig> bansSaturatedHeart,
		String chugJugLabel)
	{
		this.displayName = displayName;
		this.objectId = objectId;
		this.regions = regions;
		this.enabled = enabled;
		this.spellRequired = spellRequired;
		this.bansChugJug = bansChugJug;
		this.bansSaturatedHeart = bansSaturatedHeart;
		this.chugJugLabel = chugJugLabel;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getObjectId()
	{
		return objectId;
	}

	/**
	 * @return the config key prefix for this location, e.g. {@code "nex"} for {@code nexEnabled}
	 */
	public String getConfigPrefix()
	{
		return name().toLowerCase();
	}

	public boolean isEnabled(AccessDeniedConfig config)
	{
		return enabled.test(config);
	}

	/**
	 * @return whether anything at all is configured to be checked here — a master toggle on
	 * its own validates nothing
	 */
	public boolean hasRequirements(AccessDeniedConfig config)
	{
		return spellRequired.test(config) || bansChugJug.test(config) || bansSaturatedHeart.test(config);
	}

	public boolean requiresValidation(AccessDeniedConfig config)
	{
		return isEnabled(config) && hasRequirements(config);
	}

	public boolean bansChugJug(AccessDeniedConfig config)
	{
		return bansChugJug.test(config);
	}

	public boolean bansSaturatedHeart(AccessDeniedConfig config)
	{
		return bansSaturatedHeart.test(config);
	}

	/**
	 * @return what the Chug Jug is called here — CoX renames it to the Chugging Barrel
	 */
	public String getChugJugLabel()
	{
		return chugJugLabel;
	}

	public boolean isInRegion(int regionId)
	{
		for (int region : regions)
		{
			if (region == regionId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * @return the location covering any of the given map regions, or null if none do
	 */
	public static BossLocation findByRegions(int[] mapRegions)
	{
		if (mapRegions == null)
		{
			return null;
		}

		for (BossLocation location : values())
		{
			for (int region : mapRegions)
			{
				if (location.isInRegion(region))
				{
					return location;
				}
			}
		}
		return null;
	}
}

package com.osrs.accessdenied;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * Combination runes and the standard rune types each one stands in for when checking
 * spell requirements. Constructor arguments are the combination rune's item ID followed
 * by the rune IDs it covers.
 */
@Getter
public enum CombinationRune
{
	AETHER(30843, 566, 564),
	LAVA(4699, 554, 557),
	MIST(4695, 556, 555),
	MUD(4698, 557, 555),
	SMOKE(4697, 556, 554),
	STEAM(4694, 554, 555);

	private final int itemId;
	private final Set<Integer> substitutesFor;

	/**
	 * Reverse index, precomputed because the lookup runs per rune type on every validation.
	 */
	private static final Map<Integer, List<CombinationRune>> BY_SUBSTITUTED_RUNE = buildIndex();

	CombinationRune(int itemId, int... runeIds)
	{
		this.itemId = itemId;
		Set<Integer> set = new HashSet<>();
		for (int id : runeIds)
		{
			set.add(id);
		}
		this.substitutesFor = Collections.unmodifiableSet(set);
	}

	private static Map<Integer, List<CombinationRune>> buildIndex()
	{
		Map<Integer, List<CombinationRune>> index = new HashMap<>();
		for (CombinationRune rune : values())
		{
			for (int runeId : rune.substitutesFor)
			{
				index.computeIfAbsent(runeId, id -> new ArrayList<>()).add(rune);
			}
		}
		index.replaceAll((runeId, runes) -> List.copyOf(runes));
		return index;
	}

	/**
	 * Returns whether this combination rune can substitute for the given rune ID.
	 *
	 * @param runeId the rune item ID to check
	 * @return true if this combination rune substitutes for the given rune
	 */
	public boolean canSubstituteFor(int runeId)
	{
		return substitutesFor.contains(runeId);
	}

	/**
	 * Returns all combination runes that can substitute for the given rune ID.
	 *
	 * @param runeId the rune item ID to check
	 * @return the combination runes that substitute for the given rune, empty if none do
	 */
	public static List<CombinationRune> getSubstitutesForRune(int runeId)
	{
		return BY_SUBSTITUTED_RUNE.getOrDefault(runeId, List.of());
	}
}

package com.osrs.accessdenied;

/**
 * Mutually exclusive Chambers of Xeric spell requirement.
 *
 * <p>Thralls and Death Charge live on the Arceuus spellbook while Humidify and Vengeance
 * live on Lunar, so a CoX setup can only ever sit on one spellbook at a time. Modelling the
 * choice as a single value (rendered as a dropdown) makes the cross-spellbook conflict
 * impossible to express, so the config never has to be programmatically corrected — which in
 * turn avoids the stale-checkbox lag of RuneLite's config panel, which does not refresh on
 * programmatic config changes.
 */
public enum CoxSpellRequirement
{
	NONE("None", false, false, false, false),
	THRALLS("Thralls", true, false, false, false),
	DEATH_CHARGE("Death Charge", false, true, false, false),
	THRALLS_AND_DEATH_CHARGE("Thralls + Death Charge", true, true, false, false),
	HUMIDIFY("Humidify", false, false, true, false),
	VENGEANCE("Vengeance", false, false, false, true),
	HUMIDIFY_AND_VENGEANCE("Humidify + Vengeance", false, false, true, true);

	private final String displayName;
	private final boolean thralls;
	private final boolean deathCharge;
	private final boolean humidify;
	private final boolean vengeance;

	CoxSpellRequirement(String displayName, boolean thralls, boolean deathCharge, boolean humidify, boolean vengeance)
	{
		this.displayName = displayName;
		this.thralls = thralls;
		this.deathCharge = deathCharge;
		this.humidify = humidify;
		this.vengeance = vengeance;
	}

	public boolean requiresThralls()
	{
		return thralls;
	}

	public boolean requiresDeathCharge()
	{
		return deathCharge;
	}

	public boolean requiresHumidify()
	{
		return humidify;
	}

	public boolean requiresVengeance()
	{
		return vengeance;
	}

	public boolean requiresArceuus()
	{
		return thralls || deathCharge;
	}

	public boolean requiresLunar()
	{
		return humidify || vengeance;
	}

	/**
	 * @return the label shown in the config dropdown
	 */
	@Override
	public String toString()
	{
		return displayName;
	}

	/**
	 * Maps the four legacy boolean toggles (coxRequireSpell/coxRequireDeathCharge/
	 * coxRequireHumidify/coxRequireVengeance) to the equivalent value, for migrating configs
	 * saved before this enum existed. A cross-spellbook combination — only expressible
	 * before the two spellbooks were made mutually exclusive — resolves to its Arceuus half.
	 */
	public static CoxSpellRequirement fromLegacyFlags(boolean thralls, boolean deathCharge, boolean humidify, boolean vengeance)
	{
		if (thralls && deathCharge)
		{
			return THRALLS_AND_DEATH_CHARGE;
		}
		if (thralls)
		{
			return THRALLS;
		}
		if (deathCharge)
		{
			return DEATH_CHARGE;
		}
		if (humidify && vengeance)
		{
			return HUMIDIFY_AND_VENGEANCE;
		}
		if (humidify)
		{
			return HUMIDIFY;
		}
		if (vengeance)
		{
			return VENGEANCE;
		}
		return NONE;
	}
}

package com.osrs.accessdenied;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;

/**
 * Hides every NPC while enabled by vetoing them as the client assembles each frame.
 *
 * <p>This is the same mechanism the client's own Entity Hider plugin uses, so the two
 * coexist without interfering: the client hides an entity if any registered callback
 * vetoes it, and neither plugin can force one back into view.
 */
@Singleton
public class NpcHider implements RenderCallback
{
	private final RenderCallbackManager renderCallbackManager;

	/**
	 * Written from the AWT event thread when the side panel or a config change flips it,
	 * read from the client thread on every rendered entity.
	 */
	private volatile boolean hideNpcs;

	private boolean registered;

	@Inject
	public NpcHider(RenderCallbackManager renderCallbackManager)
	{
		this.renderCallbackManager = renderCallbackManager;
	}

	void startUp()
	{
		if (!registered)
		{
			renderCallbackManager.register(this);
			registered = true;
		}
	}

	void shutDown()
	{
		if (registered)
		{
			renderCallbackManager.unregister(this);
			registered = false;
		}

		hideNpcs = false;
	}

	void setHideNpcs(boolean hideNpcs)
	{
		this.hideNpcs = hideNpcs;
	}

	boolean isHideNpcs()
	{
		return hideNpcs;
	}

	/**
	 * {@code ui} separates the 3D model pass from the 2D overlay pass — health bars,
	 * overhead prayers, hitsplats and names. Both are vetoed, so a hidden NPC leaves
	 * nothing at all behind.
	 *
	 * <p>Vetoing the 3D pass also drops the NPC's clickbox, so a hidden NPC cannot be
	 * attacked or talked to. That is inherent to the callback and matches Entity Hider;
	 * the README warns players about it.
	 */
	@Override
	public boolean addEntity(Renderable renderable, boolean ui)
	{
		return !(hideNpcs && renderable instanceof NPC);
	}
}

package com.osrs.accessdenied;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;

/**
 * Service class responsible for validating player state against area requirements.
 * Checks actual rune counts from inventory, equipment, and rune pouch.
 */
@Slf4j
@Singleton
public class PlayerStateValidator
{
	/**
	 * Items that provide an unlimited supply of one or more standard runes.
	 * Maps item ID to the rune ID(s) the item covers. Only the charged tome
	 * variants are listed; uncharged tomes have distinct item IDs and provide nothing.
	 */
	private static final Map<Integer, int[]> INFINITE_RUNE_SOURCES = buildInfiniteRuneSources();

	/**
	 * Regular, divine (current and old), and locked divine rune pouches.
	 */
	private static final Set<Integer> RUNE_POUCH_IDS = Set.of(12791, 27281, 27086, 27509);

	private final Client client;

	@Inject
	public PlayerStateValidator(Client client)
	{
		this.client = client;
	}

	private static Map<Integer, int[]> buildInfiniteRuneSources()
	{
		final int[] air = {ItemID.AIRRUNE};
		final int[] water = {ItemID.WATERRUNE};
		final int[] earth = {ItemID.EARTHRUNE};
		final int[] fire = {ItemID.FIRERUNE};
		final int[] lava = {ItemID.FIRERUNE, ItemID.EARTHRUNE};
		final int[] mud = {ItemID.WATERRUNE, ItemID.EARTHRUNE};
		final int[] steam = {ItemID.WATERRUNE, ItemID.FIRERUNE};
		final int[] smoke = {ItemID.AIRRUNE, ItemID.FIRERUNE};
		final int[] mist = {ItemID.AIRRUNE, ItemID.WATERRUNE};
		final int[] dust = {ItemID.AIRRUNE, ItemID.EARTHRUNE};

		Map<Integer, int[]> sources = new HashMap<>();
		sources.put(ItemID.KODAI_WAND, water);
		sources.put(ItemID.TOME_OF_FIRE, fire);
		sources.put(ItemID.TOME_OF_WATER, water);

		sources.put(ItemID.STAFF_OF_AIR, air);
		sources.put(ItemID.AIR_BATTLESTAFF, air);
		sources.put(ItemID.MYSTIC_AIR_STAFF, air);
		sources.put(ItemID.STAFF_OF_WATER, water);
		sources.put(ItemID.WATER_BATTLESTAFF, water);
		sources.put(ItemID.MYSTIC_WATER_STAFF, water);
		sources.put(ItemID.STAFF_OF_EARTH, earth);
		sources.put(ItemID.EARTH_BATTLESTAFF, earth);
		sources.put(ItemID.MYSTIC_EARTH_STAFF, earth);
		sources.put(ItemID.STAFF_OF_FIRE, fire);
		sources.put(ItemID.FIRE_BATTLESTAFF, fire);
		sources.put(ItemID.MYSTIC_FIRE_STAFF, fire);
		sources.put(ItemID.LAVA_BATTLESTAFF, lava);
		sources.put(ItemID.MYSTIC_LAVA_STAFF, lava);
		sources.put(ItemID.MUD_BATTLESTAFF, mud);
		sources.put(ItemID.MYSTIC_MUD_STAFF, mud);
		sources.put(ItemID.STEAM_BATTLESTAFF, steam);
		sources.put(ItemID.MYSTIC_STEAM_BATTLESTAFF, steam);
		sources.put(ItemID.SMOKE_BATTLESTAFF, smoke);
		sources.put(ItemID.MYSTIC_SMOKE_BATTLESTAFF, smoke);
		sources.put(ItemID.MIST_BATTLESTAFF, mist);
		sources.put(ItemID.MYSTIC_MIST_BATTLESTAFF, mist);
		sources.put(ItemID.DUST_BATTLESTAFF, dust);
		sources.put(ItemID.MYSTIC_DUST_BATTLESTAFF, dust);
		return sources;
	}

	/**
	 * Spellbook varbit values: 0 = Standard, 1 = Ancient, 2 = Lunar, 3 = Arceuus.
	 */
	private static final int ANCIENT_SPELLBOOK = 1;
	private static final int LUNAR_SPELLBOOK = 2;
	private static final int ARCEUUS_SPELLBOOK = 3;

	/**
	 * Arceuus is required to cast Thralls and Death Charge.
	 */
	public boolean isOnArceuusSpellbook()
	{
		return getCurrentSpellbook() == ARCEUUS_SPELLBOOK;
	}

	/**
	 * Lunar is required to cast Humidify and Vengeance.
	 */
	public boolean isOnLunarSpellbook()
	{
		return getCurrentSpellbook() == LUNAR_SPELLBOOK;
	}

	/**
	 * Ancient is required to cast Ice Barrage and Blood Barrage.
	 */
	public boolean isOnAncientSpellbook()
	{
		return getCurrentSpellbook() == ANCIENT_SPELLBOOK;
	}

	/**
	 * Thralls, on Arceuus. Aether runes substitute for the Cosmic rune.
	 */
	public boolean hasResurrectGreaterGhostRunes()
	{
		return hasRequiredRunes(Map.of(ItemID.FIRERUNE, 10, ItemID.BLOODRUNE, 5, ItemID.COSMICRUNE, 1));
	}

	/**
	 * Death Charge, on Arceuus. Aether runes substitute for the Soul rune.
	 */
	public boolean hasDeathChargeRunes()
	{
		return hasRequiredRunes(Map.of(ItemID.DEATHRUNE, 1, ItemID.BLOODRUNE, 1, ItemID.SOULRUNE, 1));
	}

	/**
	 * Humidify, on Lunar.
	 */
	public boolean hasHumidifyRunes()
	{
		return hasRequiredRunes(Map.of(ItemID.ASTRALRUNE, 1, ItemID.FIRERUNE, 1, ItemID.WATERRUNE, 1));
	}

	/**
	 * Vengeance, on Lunar.
	 */
	public boolean hasVengeanceRunes()
	{
		return hasRequiredRunes(Map.of(ItemID.EARTHRUNE, 10, ItemID.ASTRALRUNE, 4, ItemID.DEATHRUNE, 2));
	}

	/**
	 * Ice Barrage, on Ancient. Uses no Soul or Cosmic runes, so Aether runes don't help.
	 */
	public boolean hasIceBarrageRunes()
	{
		return hasRequiredRunes(Map.of(ItemID.WATERRUNE, 6, ItemID.DEATHRUNE, 2, ItemID.BLOODRUNE, 4));
	}

	/**
	 * Blood Barrage, on Ancient. Aether runes substitute for the Soul rune.
	 */
	public boolean hasBloodBarrageRunes()
	{
		return hasRequiredRunes(Map.of(ItemID.BLOODRUNE, 4, ItemID.SOULRUNE, 1, ItemID.DEATHRUNE, 4));
	}

	/**
	 * Scan inventory and worn equipment for items that grant unlimited runes
	 * (Kodai wand, charged tomes, elemental and combination staves).
	 * This is a capability check matching the previous Kodai behaviour: carrying the
	 * item is enough, it does not need to be wielded. As a result it can over-suppress
	 * when a spell needs two elements covered only by two staves that cannot be wielded
	 * at once (e.g. Humidify with separate fire and water staves); this only affects
	 * trivial single-rune requirements and is accepted.
	 *
	 * @return set of standard rune IDs the player has an unlimited supply of
	 */
	private Set<Integer> getInfiniteRuneSources()
	{
		Set<Integer> covered = new HashSet<>();

		anyCarriedOrWornItemMatches(item ->
		{
			int[] runes = INFINITE_RUNE_SOURCES.get(item.getId());
			if (runes != null)
			{
				for (int runeId : runes)
				{
					covered.add(runeId);
				}
			}
			return false;
		});

		return covered;
	}

	/**
	 * Scans the player's inventory then worn equipment, stopping as soon as {@code matcher}
	 * matches an item. Skips either container if it isn't present (e.g. not yet loaded).
	 *
	 * @return true if some item matched, false if none did
	 */
	private boolean anyCarriedOrWornItemMatches(Predicate<Item> matcher)
	{
		int[] containerIds = {InventoryID.INV, InventoryID.WORN};

		for (int containerId : containerIds)
		{
			ItemContainer container = client.getItemContainer(containerId);
			if (container == null)
			{
				continue;
			}

			for (Item item : container.getItems())
			{
				if (item != null && matcher.test(item))
				{
					return true;
				}
			}
		}

		return false;
	}

	public boolean hasChugJug()
	{
		return anyInventoryItemMatches(item -> item.getId() == ItemID.MM_PREPOT_DEVICE);
	}

	public boolean hasSaturatedHeart()
	{
		return anyInventoryItemMatches(item -> item.getId() == ItemID.SATURATED_HEART);
	}

	/**
	 * As {@link #anyCarriedOrWornItemMatches}, but the inventory only — worn equipment
	 * doesn't count for items that are banned rather than required.
	 */
	private boolean anyInventoryItemMatches(Predicate<Item> matcher)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return false;
		}

		for (Item item : inventory.getItems())
		{
			if (item != null && matcher.test(item))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Check if the player has the required runes, accounting for combination runes.
	 * Substitution is driven by {@link CombinationRune}: each rune type is checked
	 * independently by summing the player's standard runes with any combination runes
	 * that cover that type. This matches OSRS behaviour, where the game validates each
	 * rune type independently — a single Steam rune counts toward both the Fire check
	 * and the Water check without being "spent" between the two.
	 * Runes covered by an infinite rune source (staff, charged tome, Kodai wand) are
	 * treated as satisfied regardless of quantity.
	 *
	 * @param requiredRunes Map of rune ID to required quantity
	 * @return true if the player has sufficient runes, false otherwise
	 */
	private boolean hasRequiredRunes(Map<Integer, Integer> requiredRunes)
	{
		Map<Integer, Integer> totalRunes = getTotalRuneCounts();
		Set<Integer> infiniteRunes = getInfiniteRuneSources();

		for (Map.Entry<Integer, Integer> entry : requiredRunes.entrySet())
		{
			int runeId = entry.getKey();

			if (infiniteRunes.contains(runeId))
			{
				continue;
			}

			int available = totalRunes.getOrDefault(runeId, 0);

			for (CombinationRune combinationRune : CombinationRune.getSubstitutesForRune(runeId))
			{
				available += totalRunes.getOrDefault(combinationRune.getItemId(), 0);
			}

			if (available < entry.getValue())
			{
				log.debug("Missing rune {} - need {}, have {}", runeId, entry.getValue(), available);
				return false;
			}
		}

		return true;
	}

	/**
	 * Check if the player has a Book of the Dead in their inventory or equipped.
	 * Book of the Dead is required to cast Thralls.
	 *
	 * @return true if the player has a Book of the Dead, false otherwise
	 */
	public boolean hasBookOfTheDead()
	{
		return anyCarriedOrWornItemMatches(item -> item.getId() == ItemID.BOOK_OF_THE_DEAD);
	}

	/**
	 * @return Map of rune ID to total quantity across the inventory and the rune pouch
	 */
	private Map<Integer, Integer> getTotalRuneCounts()
	{
		Map<Integer, Integer> runeCounts = new HashMap<>();

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item != null && item.getId() > 0)
				{
					runeCounts.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}

		Map<Integer, Integer> runePouchRunes = getRunePouchContents();
		for (Map.Entry<Integer, Integer> entry : runePouchRunes.entrySet())
		{
			runeCounts.merge(entry.getKey(), entry.getValue(), Integer::sum);
		}

		return runeCounts;
	}

	/**
	 * Reads the rune pouch's four (type varbit, quantity varbit) slot pairs, mapping each
	 * type key through the RUNEPOUCH_RUNE enum to an item ID. A type key of 0 is an empty
	 * slot. The varbits persist after the pouch is deposited, so the pouch must be
	 * confirmed present first or stale contents would be counted.
	 *
	 * @return Map of rune ID to quantity in the rune pouch
	 */
	private Map<Integer, Integer> getRunePouchContents()
	{
		Map<Integer, Integer> contents = new HashMap<>();

		if (!hasRunePouchInInventory())
		{
			return contents;
		}

		EnumComposition runepouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runepouchEnum == null)
		{
			log.debug("Rune pouch enum not available");
			return contents;
		}

		int[] runeVarbits = {
			VarbitID.RUNE_POUCH_TYPE_1,
			VarbitID.RUNE_POUCH_TYPE_2,
			VarbitID.RUNE_POUCH_TYPE_3,
			VarbitID.RUNE_POUCH_TYPE_4
		};
		int[] amountVarbits = {
			VarbitID.RUNE_POUCH_QUANTITY_1,
			VarbitID.RUNE_POUCH_QUANTITY_2,
			VarbitID.RUNE_POUCH_QUANTITY_3,
			VarbitID.RUNE_POUCH_QUANTITY_4
		};

		for (int i = 0; i < runeVarbits.length; i++)
		{
			int runeEnumKey = client.getVarbitValue(runeVarbits[i]);
			int amount = client.getVarbitValue(amountVarbits[i]);

			if (runeEnumKey <= 0 || amount <= 0)
			{
				continue;
			}

			contents.put(runepouchEnum.getIntValue(runeEnumKey), amount);
		}

		return contents;
	}

	private boolean hasRunePouchInInventory()
	{
		return anyInventoryItemMatches(item -> RUNE_POUCH_IDS.contains(item.getId()));
	}

	private int getCurrentSpellbook()
	{
		return client.getVarbitValue(VarbitID.SPELLBOOK);
	}
}

