	@Example
	void getSubstitutesForRuneReturnsEmptyForUnsubstitutableRune()
	{
		// No combination rune substitutes for Death runes
		List<CombinationRune> result = CombinationRune.getSubstitutesForRune(DEATH_RUNE_ID);
