		@ForAll @IntRange(min = 1, max = 10) int aetherRunes
	)
	{
		Item[] items = new Item[]{
			createItem(FIRE_RUNE_ID, 10),
			createItem(BLOOD_RUNE_ID, 5),
			createItem(COSMIC_RUNE_ID, cosmicRunes),
			createItem(AETHER_RUNE_ID, aetherRunes),
