		boolean result = validator.hasResurrectGreaterGhostRunes();
		assertThat(result)
			.as("With Fire:%d + Lava:%d (total:%d), expected:%s", fireRunes, lavaRunes, totalFireEquivalent, shouldPass)
			.isEqualTo(shouldPass);
